SourceCode.Declaration:
/// <summary>
/// Data contract class for managing bulk workflow work items.
/// </summary>
/// Added for CFR4 bulk approval AR invoice.
[DataContractAttribute]
[SysOperationContractProcessing(classStr(METBulkFreeTextInvoiceWorkflowSubmissionMainUIBuilder))]
class METBulkFreeTextInvoiceWorkflowSubmissionMainContract implements SysOperationValidatable
{
    int                         noOfThreads;
    str                         packedQuery;
    Filename                    fileName;

}

Method.Source:
/// <summary>
/// Gets or sets the number of threads.
/// </summary>
/// <param name="_noOfThreads">The number of threads.</param>
/// <returns>The number of threads.</returns>
[DataMemberAttribute,
SysOperationLabelAttribute("@SYS109551"),
SysOperationDisplayOrderAttribute('1')]
public int parmNoOfThreads(int _noOfThreads = noOfThreads)
{
    noOfThreads = _noOfThreads;

    return noOfThreads;
}

/// <summary>
/// Gets or sets the file name.
/// </summary>
/// <param name="_fileName">The DMF file name.</param>
/// <returns>The DMF file name.</returns>
[DataMemberAttribute,
SysOperationLabelAttribute("@MET:METFTIDMFImportFileName"),
SysOperationDisplayOrderAttribute('2')]
public Filename parmDMFFileName(Filename _fileName = fileName)
{
    fileName = _fileName;

    return fileName;
}

/// <summary>
/// Gets or sets the packed query.
/// </summary>
/// <param name="_packedQuery">The packed query string.</param>
/// <returns>The packed query string.</returns>
[DataMemberAttribute,
    AifQueryTypeAttribute('_packedQuery', querystr(METBulkWFFreeTextInvoiceSubmission))]
public str parmQuery(str _packedQuery = packedQuery)
{
    packedQuery = _packedQuery;

    return packedQuery;
}

/// <summary>
/// Gets the query object from the packed query string.
/// </summary>
/// <returns>The query object.</returns>
internal Query getQuery()
{
    return new Query(SysOperationHelper::base64Decode(packedQuery));
}

/// <summary>
/// Sets the query object and packs it into a string.
/// </summary>
/// <param name="_query">The query object.</param>
internal void setQuery(Query _query)
{
    packedQuery = SysOperationHelper::base64Encode(_query.pack());
}

/// <summary>
/// Validate DMF file name.
/// </summary>
/// <returns>return true if validation succeeded; else false.</returns>
public boolean validate()
{
    CustInvoiceTable  invoiceTable;
    boolean           ret = true;

    if (!fileName)
    {
        ret = checkFailed(strFmt("@SYS26332", fieldId2PName(tableNum(CustInvoiceTable), fieldNum(CustInvoiceTable, METDMFImportFileName))));
    }
    else
    {
        select firstonly RecId from invoiceTable
            where invoiceTable.METDMFImportFileName == this.parmDMFFileName();

        if (invoiceTable.RecId == 0)
        {
            ret = checkFailed("@MET:METFTIDMFFileNameValid");
        }
    }

    return ret;
}
